mapper.select:
select t.id as id, t.dict_item_code AS dictItemCode, t.dict_item_name AS dictItemName, t.sort as sort, t.is_enabled AS enabled, t.is_builtin AS builtin, t.icon AS icon, t.remark AS remark, c.real_name as createdBy, t.created_time as createdTime, u.real_name as lastUpdatedBy, t.last_updated_time as lastUpdatedTime from hyn_sys_dict_item t left join hyn_sys_user_snapshot c on t.created_by = c.id left join hyn_sys_user_snapshot u on t.last_updated_by = u.id
t.dict_type_id = #{dictTypeId}
AND t.dict_item_code LIKE #{dictItemCode_pattern}
AND t.dict_item_name LIKE #{dictItemName_pattern}
and t.is_enabled = #{enabled}
AND t.is_builtin = #{builtin}
ORDER BY
${sortField}
t.sort
ASC DESC

SELECT t.dict_type_code AS dictTypeCode, i.dict_item_code AS VALUE, i.dict_item_name AS label, t.icon_type AS iconType, i.icon AS icon FROM hyn_sys_dict_item i INNER JOIN hyn_sys_dict_type t ON i.dict_type_id = t.id WHERE i.is_enabled = 1 AND t.is_enabled = 1 AND t.dict_type_code IN
#{item}
ORDER BY t.dict_type_code, i.sort
